def seed_projects(apps, schema_editor):
    Project = apps.get_model('website', 'Project')
    for title, year, state, gender, category, description, document_url in SEED_PROJECTS:
        Project.objects.update_or_create(
            title=title,
            year=year,
            defaults={
                'state': state,
                'gender': gender,
                'category': category,
                'description': description,
                'document_url': document_url,
                'is_active': True,
            },
        )


def unseed_projects(apps, schema_editor):
    Project = apps.get_model('website', 'Project')
    for title, year, *_ in SEED_PROJECTS:
        Project.objects.filter(title=title, year=year).delete()


